function Scanner(){const [address,setAddress]=useState(''),[report,setReport]=useState<any>(null),[busy,setBusy]=useState(false),[error,setError]=useState('');const {notify}=useApp();const scan=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);setError('');setReport(null);try{const r=await fetch('/api/scan?address='+encodeURIComponent(address));const d:any=await r.json();if(!r.ok)throw new Error(d.error);setReport(d)}catch(e:any){setError(e.message||'The explorer is temporarily unavailable.')}finally{setBusy(false)}};const exportCard=()=>{if(!report)return;const text=JSON.stringify({network:'Robinhood Chain',indicator:report.score,findings:report.findings.map((x:any)=>x.title),sampleSize:report.transactions.length,generatedAt:report.updatedAt},null,2);const url=URL.createObjectURL(new Blob([text],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='rello-exposure-card.json';a.click();URL.revokeObjectURL(url);notify('Redacted card exported')};return <div className="page-wrap scanner-page"><PageTitle tag="EXPOSURE SCANNER / READ ONLY" title="See your public footprint." desc="Balances, counterparties and activity. The wallet view anyone can inspect."/><form className="scan-form" onSubmit={scan}><Eye size={22}/><input aria-label="Wallet address" value={address} onChange={e=>setAddress(e.target.value)} placeholder="Paste a Robinhood Chain address · 0x…" pattern="0x[a-fA-F0-9]{40}" required/><Button type="submit" disabled={busy}>{busy?'Reading public data…':'Scan wallet'}</Button></form><div className="scan-assurance"><span><Shield size={15}/>Public data only</span><span><Eye size={15}/>No connection or signature</span><span><Lock size={15}/>No private-key access</span></div>{error&&<div className="error-banner" role="alert"><AlertCircle/>{error}</div>}{report?<div className="scan-report"><div className="report-head"><span className="mono">PUBLIC FOOTPRINT REPORT</span><CopyButton text={address}/></div><div className="report-grid"><div className="score"><strong>{report.score}<small>/100</small></strong><span>PUBLIC ACTIVITY INDICATOR</span><p>Based on the returned transaction sample. Not an identity prediction or a security audit.</p></div><div><code>{short(address)}</code><div className="stats-row"><div><span>ETH balance</span><strong>{report.balance}</strong></div><div><span>Recent transactions</span><strong>{report.transactions.length}</strong></div><div><span>Counterparties</span><strong>{report.counterparties.length}</strong></div></div><div className="findings">{report.findings.map((f:any)=><div key={f.title}><Eye size={18}/><span>{f.title}<small>{f.description}</small></span></div>)}</div></div></div><div className="panel"><div className="panel-heading"><h3>Recent public transactions</h3><a href={report.explorer} target="_blank" rel="noreferrer">Open explorer <ExternalLink size={14}/></a></div>{report.transactions.length?<div className="transaction-list">{report.transactions.map((t:any)=><div key={t.hash}><a href={'https://robinhoodchain.blockscout.com/tx/'+t.hash} target="_blank" rel="noreferrer"><code>{short(t.hash)}</code></a><span>{t.method||'Transfer'}</span><span>{t.timestamp?new Date(t.timestamp).toLocaleString():'—'}</span><span>{t.status}</span></div>)}</div>:<Empty title="No transactions in this sample" desc="A lack of recent results does not establish that a wallet is private."/>}</div><div className="button-row"><Button secondary onClick={exportCard}><Download size={16}/>Export redacted card</Button><span className="muted">Address, balance and counterparties are excluded.</span></div></div>:!busy&&<div className="scan-placeholder"><div className="scan-grid-art"><Eye size={36}/></div><h3>Your wallet, from the outside.</h3><p>Paste an address to read its public chain footprint.</p></div>}</div>}
