function Modal({title,children,close}:{title:string;children:ReactNode;close:()=>void}){const ref=useRef<HTMLDivElement>(null);useEffect(()=>{const prev=document.activeElement as HTMLElement;const overflow=document.body.style.overflow;document.body.style.overflow='hidden';const box=ref.current;const elements=()=>Array.from(box?.querySelectorAll<HTMLElement>('button,input,a,select,[tabindex="0"]')||[]).filter(x=>!x.hasAttribute('disabled'));elements()[0]?.focus();const fn=(e:KeyboardEvent)=>{if(e.key==='Escape')close();if(e.key==='Tab'){const xs=elements(),first=xs[0],last=xs[xs.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}};document.addEventListener('keydown',fn);return()=>{document.body.style.overflow=overflow;document.removeEventListener('keydown',fn);prev?.focus()};},[]);return <div className="modal-backdrop" onClick={close}><div className="modal" ref={ref} role="dialog" aria-modal="true" aria-label={title} onClick={e=>e.stopPropagation()}><div className="modal-head"><h2>{title}</h2><button onClick={close} aria-label="Close dialog"><X size={21}/></button></div>{children}</div></div>}
export default function Rello({path}:{path:string}){
 const [wallets,setWallets]=useState<WalletInfo[]>([]),[address,setAddress]=useState(''),[balance,setBalance]=useState<any>(null),[modal,setModal]=useState<'wallet'|'access'|'transaction'|null>(null),[busy,setBusy]=useState(''),[error,setError]=useState(''),[toast,setToast]=useState(''),[action,setAction]=useState(''),[motion,setMotion]=useState(true),[restoring,setRestoring]=useState(true),[selected,setSelected]=useState<WalletInfo|null>(null),[access,setAccess]=useState<HolderAccess|null>(null),[checking,setChecking]=useState(false);
 const providerRef=useRef<Provider|null>(null),pending=useRef(false),nextHop=useRef<string|null>(null),readId=useRef(0),addressRef=useRef(address);addressRef.current=address;
 const notify=(msg:string)=>setToast(msg);
 useEffect(()=>{if(!toast)return;const t=setTimeout(()=>setToast(''),4500);return()=>clearTimeout(t)},[toast]);
 useEffect(()=>{if(!window.location.hash)return;const frame=requestAnimationFrame(()=>document.getElementById(decodeURIComponent(window.location.hash.slice(1)))?.scrollIntoView({behavior:'instant',block:'start'}));return()=>cancelAnimationFrame(frame)},[path]);
 const connect=()=>{setError('');setModal('wallet')};
 const refreshAccess=async(walletAddress=address):Promise<HolderAccess|null>=>{const id=++readId.current;if(!walletAddress){setAccess(null);setChecking(false);return null}setChecking(true);let result:HolderAccess;try{const r=await fetch('/api/access?address='+encodeURIComponent(walletAddress),{cache:'no-store'});result=await r.json();if(!r.ok||result.address?.toLowerCase()!==walletAddress.toLowerCase())throw Error('Unable to verify holdings.')}catch{result={address:walletAddress,eligible:false,status:'unavailable',reason:'Unable to verify RELLO holdings. Please retry.',checkedAt:new Date().toISOString()}}if(id===readId.current&&addressRef.current.toLowerCase()===walletAddress.toLowerCase()){setAccess(result);setChecking(false)}return result};
 useEffect(()=>{if(!address){readId.current++;setAccess(null);setBalance(null);setChecking(false);return}let alive=true;fetch('/api/cash/balance?address='+address).then(r=>r.json()).then((d:any)=>{if(alive&&!d.error)setBalance(d)}).catch(()=>{});refreshAccess(address);const interval=setInterval(()=>refreshAccess(address),60000);const focus=()=>refreshAccess(address);window.addEventListener('focus',focus);return()=>{alive=false;readId.current++;clearInterval(interval);window.removeEventListener('focus',focus)}},[address]);
 useEffect(()=>{const add=(w:WalletInfo)=>setWallets(ws=>ws.some(x=>x.provider===w.provider)?ws:[...ws,w]);const fn=(e:any)=>{const d=e.detail;if(d?.provider&&d?.info)add({name:d.info.name,icon:d.info.icon,rdns:d.info.rdns,provider:d.provider})};window.addEventListener('eip6963:announceProvider',fn);window.dispatchEvent(new Event('eip6963:requestProvider'));const eth=(window as any).ethereum;if(eth)add({name:eth.isMetaMask?'MetaMask':eth.isCoinbaseWallet?'Coinbase Wallet':'Browser wallet',rdns:'injected',provider:eth});setMotion(!matchMedia('(prefers-reduced-motion: reduce)').matches);const t=setTimeout(()=>setRestoring(false),600);return()=>{window.removeEventListener('eip6963:announceProvider',fn);clearTimeout(t)}},[]);
 useEffect(()=>{if(selected)return;const saved=sessionStorage.getItem('rello-wallet-provider');if(!saved)return;const w=wallets.find(w=>(w.rdns||w.name)===saved);if(!w)return;let alive=true;setRestoring(true);w.provider.request({method:'eth_accounts'}).then(accounts=>{if(alive&&accounts?.[0]&&/^0x[a-fA-F0-9]{40}$/.test(accounts[0])){providerRef.current=w.provider;setSelected(w);setAddress(accounts[0]);setRestoring(false);setModal(null)}}).catch(()=>{}).finally(()=>{if(alive)setRestoring(false)});return()=>{alive=false}},[wallets,selected]);
 useEffect(()=>{if(!selected)return;const change=(accounts:string[])=>{readId.current++;setAccess(null);setBalance(null);setAddress(accounts?.[0]&&/^0x[a-fA-F0-9]{40}$/.test(accounts[0])?accounts[0]:'')};const chainChange=()=>{readId.current++;setAccess(null);refreshAccess(addressRef.current)};const disconnected=()=>change([]);selected.provider.on?.('disconnect',disconnected);selected.provider.on?.('accountsChanged',change);selected.provider.on?.('chainChanged',chainChange);return()=>{selected.provider.removeListener?.('disconnect',disconnected);selected.provider.removeListener?.('accountsChanged',change);selected.provider.removeListener?.('chainChanged',chainChange)}},[selected]);
 useEffect(()=>{const click=(e:MouseEvent)=>{const a=(e.target as Element)?.closest?.('a[href]') as HTMLAnchorElement|null;if(!a||e.defaultPrevented||e.button!==0||e.ctrlKey||e.metaKey||e.shiftKey||e.altKey||a.target==='_blank')return;const url=new URL(a.href,location.href);if(url.origin===location.origin&&/^\/app(?:\/|$)/.test(url.pathname)&&!address){e.preventDefault();nextHop.current=url.pathname+url.search+url.hash;connect()}};document.addEventListener('click',click,true);return()=>document.removeEventListener('click',click,true)},[address]);
 useEffect(()=>{if(/^\/app(?:\/|$)/.test(path)&&!restoring&&!address)connect()},[path,restoring,address]);
 const transact=async(label='Submit transaction')=>{setAction(label);if(!address){pending.current=true;connect();return}const current=address;try{const accounts=await providerRef.current?.request({method:'eth_accounts'});if(accounts?.[0]?.toLowerCase()!==current.toLowerCase()){readId.current++;setAccess(null);setAddress('');pending.current=true;connect();return}}catch{setAccess(null);connect();return}const result=await refreshAccess(current);if(addressRef.current!==current)return;setModal(result?.eligible?'transaction':'access')};
 const connectWallet=async(w:WalletInfo)=>{setBusy(w.name);setError('');try{const accounts=await w.provider.request({method:'eth_requestAccounts'});if(!accounts?.[0]||!/^0x[a-fA-F0-9]{40}$/.test(accounts[0]))throw Error('No wallet address returned.');providerRef.current=w.provider;setSelected(w);sessionStorage.setItem('rello-wallet-provider',w.rdns||w.name);setAddress(accounts[0]);addressRef.current=accounts[0];setRestoring(false);setModal(null);const hop=nextHop.current;nextHop.current=null;if(hop&&hop!==location.pathname+location.search+location.hash){location.assign(hop);return}if(pending.current){pending.current=false;const result=await refreshAccess(accounts[0]);setModal(result?.eligible?'transaction':'access')}}catch(e:any){setError(e.code===4001?'Connection was declined. You can try again.':e.message||'Unable to connect this wallet.')}finally{setBusy('')}};
 const disconnect=()=>{readId.current++;sessionStorage.removeItem('rello-wallet-provider');setSelected(null);setAddress('');setBalance(null);setAccess(null);providerRef.current=null;setModal(null);notify('Wallet disconnected from this site')};
 const isWorkspace=path.startsWith('/app')||path==='/run';let content:ReactNode;if(path==='/')content=<CinematicHome enabled={motion} privacy={<PrivacyPanel/>} code={<CodeBlock/>}/>;else if(isWorkspace&&['/app','/app/pay','/app/receive','/app/move','/app/agents','/run'].includes(path))content=<Workspace path={path}/>;else if(path==='/agents')content=<div className="page-wrap"><HolderGate><AgentConsole/></HolderGate></div>;else if(path==='/dev')content=<Developer/>;else if(path.startsWith('/docs'))content=<Documentation slug={path.replace(/^\/docs\/?/,'')}/>;else if(path==='/scan')content=<Scanner/>;else if(path==='/live')content=<ActivityPage/>;else if(path==='/download')content=<Mobile/>;else if(path==='/alerts')content=<Alerts/>;else if(path==='/terms'||path==='/privacy')content=<Legal privacy={path==='/privacy'}/>;else content=<NotFound/>;return <Context.Provider value={{address,balance,connect,transact,notify,access,checking,refreshAccess}}><div className={`site ${motion?'':'motion-paused'} ${path==='/'?'cinema-site':''}`}><a className="skip-link" href="#main">Skip to content</a>{path==='/'&&<CinematicEntrance enabled={motion}/>}<Header/><main id="main" key={path}>{path.startsWith('/app')&&!address?<div className="page-wrap narrow wallet-required"><Tag>YOUR WORKSPACE</Tag><h1>Start with your wallet.</h1><p>Connect your wallet to open the Rello app. Transaction features require more than $150 worth of $RELLO.</p><Button onClick={connect} disabled={restoring}><Wallet size={18}/>{restoring?'Checking your wallet…':'Connect wallet'}</Button></div>:content}</main>{!isWorkspace&&!path.startsWith('/docs')&&<Footer/>}<button className="motion-control" aria-label={motion?'Pause background motion':'Enable background motion'} onClick={()=>{setMotion(!motion);document.querySelectorAll('video').forEach(v=>{if(motion)v.pause();else v.play().catch(()=>{})})}}>{motion?<Pause size={14}/>:<Play size={14}/>}<span>MOTION {motion?'ON':'OFF'}</span></button>{toast&&<div className="toast" role="status"><CheckCircle2 size={18}/>{toast}</div>}{modal==='wallet'&&<Modal title={address?'Your wallet':'Connect your wallet'} close={()=>{setModal(null);pending.current=false;nextHop.current=null}}>{address?<><div className="address-box"><Wallet/><code>{address}</code></div><p className="muted">Wallet connection does not authorize a payment.</p><Button secondary onClick={disconnect}>Disconnect wallet</Button></>:<><p className="muted">Choose a wallet available in your browser. Rello never asks for your recovery phrase.</p><div className="wallet-options">{wallets.map((w,i)=><button disabled={!!busy} key={i} onClick={()=>connectWallet(w)}>{w.icon&&/^data:image\//.test(w.icon)?<img src={w.icon} alt=""/>:<BrandLogo name={w.name}/>}<span>{w.name}<small>{busy===w.name?'Waiting for your wallet…':'Browser wallet'}</small></span><ChevronRight size={17}/></button>)}</div>{!wallets.length&&<div className="wallet-empty"><Wallet size={28}/><h3>No wallet detected in this browser</h3><p>Open this site in your wallet’s browser, or install a wallet extension, then return here.</p></div>}<div className="wallet-links">{[['MetaMask','https://metamask.io/download/'],['Coinbase Wallet','https://www.coinbase.com/wallet'],['Rabby','https://rabby.io/'],['Trust Wallet','https://trustwallet.com/download'],['Rainbow','https://rainbow.me/']].map(([name,url])=><a key={name} href={url} target="_blank" rel="noreferrer"><BrandLogo name={name}/><span>{name}<small>Get wallet ↗</small></span><ExternalLink size={14}/></a>)}</div>{error&&<p className="error" role="alert">{error}</p>}<p className="wallet-foot"><Shield size={14}/>Connection only · No funds move</p></>}</Modal>}{modal==='access'&&<Modal title="RELLO holder access" close={()=>setModal(null)}><HolderGate><p>Holder access verified.</p></HolderGate></Modal>}{modal==='transaction'&&<Modal title="Transaction unavailable" close={()=>setModal(null)}><div className="transaction-notice"><div><Lock size={28}/></div><span className="mono">{action.toUpperCase()}</span><h3>Review here.<br/>Move funds when enabled.</h3><p>This interface prepares payment plans. Live payment submission, escrow funding, handle registration and settlement are not enabled for Rello yet.</p><p><b>No funds were moved. No transaction or token approval was requested.</b></p><Button onClick={()=>setModal(null)}>Return to workspace</Button><Link href="/docs/escrow" className="text-link" onClick={()=>setModal(null)}>Read the payment model</Link></div></Modal>}</div></Context.Provider>}
